{
  "$schema": "https://open-design.ai/schemas/plugin.v1.json",
  "specVersion": "1.0.0",
  "name": "example-wireframe-sketch",
  "title": "Wireframe Sketch",
  "title_i18n": {
    "zh-CN": "线框草图",
    "zh-TW": "線框草圖",
    "ja": "ワイヤーフレームスケッチ",
    "ko": "와이어프레임 스케치",
    "de": "Wireframe-Skizze",
    "fr": "Wireframe Esquisse",
    "ru": "Вайрфрейм-эскиз",
    "es": "Wireframe Boceto",
    "pt-BR": "Wireframe Esboço",
    "it": "Wireframe Sketch",
    "vi": "Wireframe Phác Thảo",
    "pl": "Szkic Wireframe",
    "id": "Sketsa Wireframe",
    "nl": "Wireframe Schets",
    "ar": "رسم Wireframe تخطيطي",
    "tr": "Wireframe Taslak",
    "uk": "Вайрфрейм-ескіз",
    "en": "Wireframe Sketch"
  },
  "version": "0.1.0",
  "description": "A hand-drawn wireframe exploration — graph-paper background, marker / pencil tone, multiple tab labels for variants, sticky-note annotations, scribbled chart placeholders, hatched fills. Reads like a designer's whiteboard before any pixels are committed. Use when the brief asks for \"wireframe\", \"sketch wireframe\", \"hand-drawn\", \"lo-fi\", \"whiteboard\", \"草稿\", or \"手绘原型\".",
  "description_i18n": {
    "zh-CN": "手绘风格的线框图，包含方格纸背景、马克笔/铅笔质感、多标签页变体、便签注释、图表占位符和阴影填充。适用于「线框图」「草图线框」「手绘」「低保真」「白板」「草稿」「手绘原型」等需求。",
    "zh-TW": "手繪風格的線框圖，包含方格紙背景、麥克筆/鉛筆質感、多標籤頁變體、便利貼註解、圖表佔位符和陰影填充。適用於「線框圖」「草圖線框」「手繪」「低保真」「白板」「草稿」「手繪原型」等需求。",
    "ja": "手描き風のワイヤーフレーム。方眼紙の背景、マーカー/鉛筆のトーン、複数のタブラベル、付箋メモ、ラフなチャート、ハッチング塗りを収録。「ワイヤーフレーム」「スケッチ」「手描き」「ローファイ」「ホワイトボード」などの要件に最適。",
    "ko": "손그림 스타일의 와이어프레임. 모눈종이 배경, 마커/연필 톤, 여러 탭 레이블, 포스트잇 주석, 차트 플레이스홀더, 해칭 채우기 포함. '와이어프레임', '스케치', '손그림', '로우파이', '화이트보드' 등의 요구사항에 적합.",
    "de": "Handgezeichnetes Wireframe mit Karopapier-Hintergrund, Marker-/Bleistiftton, Tabs für Varianten, Haftnotiz-Anmerkungen und skizzierten Diagramm-Platzhaltern. Ideal für Anfragen nach Wireframe, Sketch, Lo-Fi oder Whiteboard-Designs.",
    "fr": "Wireframe dessiné à la main avec fond papier millimétré, tons marqueur/crayon, onglets multiples, annotations post-it et graphiques esquissés. Idéal pour les demandes de wireframe, croquis, lo-fi ou tableau blanc.",
    "ru": "Вайрфрейм в стиле ручного наброска: фон в клетку, текстура маркера/карандаша, варианты вкладок, стикеры с заметками и заштрихованные заполнения. Подходит для запросов «вайрфрейм», «скетч», «lo-fi», «доска».",
    "es": "Wireframe dibujado a mano con fondo de papel cuadriculado, tono de marcador/lápiz, pestañas múltiples, notas adhesivas y marcadores de gráficos. Ideal para solicitudes de wireframe, boceto, lo-fi o pizarra.",
    "pt-BR": "Wireframe desenhado à mão com fundo de papel quadriculado, tom de marcador/lápis, abas múltiplas, notas adesivas e placeholders de gráficos. Ideal para solicitações de wireframe, sketch, lo-fi ou quadro branco.",
    "it": "Wireframe disegnato a mano con sfondo a quadretti, tono pennarello/matita, schede multiple, annotazioni su post-it e segnaposto per grafici. Ideale per richieste di wireframe, sketch, lo-fi o lavagna.",
    "vi": "Wireframe vẽ tay với nền giấy kẻ ô, tông bút dạ/chì, nhiều tab nhãn, ghi chú giấy nhớ và biểu đồ phác họa. Phù hợp cho yêu cầu wireframe, sketch, lo-fi hoặc bảng trắng.",
    "pl": "Ręcznie rysowany wireframe z tłem w kratkę, tonem markera/ołówka, wieloma zakładkami, notatkami na karteczkach i szkicami wykresów. Idealny do zapytań o wireframe, szkic, lo-fi lub tablicę.",
    "id": "Wireframe yang digambar tangan dengan latar kertas kotak-kotak, gaya spidol/pensil, tab ganda, catatan tempel, dan placeholder grafik sketsa. Cocok untuk permintaan wireframe, sketsa, lo-fi, atau papan tulis.",
    "nl": "Handgetekend wireframe met ruitjespapier achtergrond, marker-/potloodtoon, meerdere tabbladen, plaknotities en geschetste grafieken. Ideaal voor verzoeken naar wireframe, sketch, lo-fi of whiteboard.",
    "ar": "إطار سلكي مرسوم يدويًا مع خلفية ورق رسم بياني، نغمة قلم تحديد/رصاص، علامات تبويب متعددة، ملاحظات لاصقة وعناصر نائبة للمخططات. مثالي لطلبات wireframe أو sketch أو lo-fi أو السبورة البيضاء.",
    "tr": "Elle çizilmiş wireframe: kareli kağıt arka plan, kalem/işaretleyici ton, çoklu sekme etiketleri, yapışkan not açıklamaları ve taslak grafik yer tutucular. Wireframe, sketch, lo-fi veya beyaz tahta talepleri için ideal.",
    "uk": "Вайрфрейм у стилі ручного начерку: фон у клітинку, текстура маркера/олівця, варіанти вкладок, стікери із замітками та заштриховані заповнення. Підходить для запитів «вайрфрейм», «ескіз», «lo-fi», «дошка».",
    "en": "A hand-drawn wireframe exploration — graph-paper background, marker / pencil tone, multiple tab labels for variants, sticky-note annotations, scribbled chart placeholders, hatched fills. Reads like a designer's whiteboard before any pixels are committed. Use when the brief asks for \"wireframe\", \"sketch wireframe\", \"hand-drawn\", \"lo-fi\", \"whiteboard\", \"草稿\", or \"手绘原型\"."
  },
  "license": "MIT",
  "author": {
    "name": "Open Design",
    "url": "https://github.com/nexu-io"
  },
  "homepage": "https://github.com/nexu-io/open-design/tree/main/plugins/_official/examples/wireframe-sketch",
  "tags": [
    "example",
    "first-party",
    "prototype",
    "design",
    "web",
    "desktop",
    "wireframe",
    "sketch-wireframe",
    "lo-fi-mockup",
    "hand-drawn",
    "whiteboard-sketch",
    "low-fidelity",
    "untitled"
  ],
  "compat": {
    "agentSkills": [
      {
        "path": "./SKILL.md"
      }
    ]
  },
  "od": {
    "kind": "scenario",
    "taskKind": "new-generation",
    "mode": "prototype",
    "platform": "desktop",
    "scenario": "design",
    "surface": "web",
    "preview": {
      "type": "html",
      "entry": "./example.html"
    },
    "useCase": {
      "query": {
        "en": "Sketch a hand-drawn wireframe v0.1 for a portal — four tabbed variants on graph paper, marker headlines, sticky-note annotations, hatched chart placeholders.",
        "zh-CN": "使用这个插件完成以下任务：Sketch a hand-drawn wireframe v0.1 for a portal — four tabbed variants on graph paper, marker headlines, sticky-note annotations, hatched chart placeholders."
      },
      "exampleOutputs": [
        {
          "path": "./example.html",
          "title": "Wireframe Sketch"
        }
      ]
    },
    "context": {
      "skills": [
        {
          "path": "./SKILL.md"
        }
      ],
      "assets": [
        "./example.html"
      ]
    },
    "pipeline": {
      "stages": [
        {
          "id": "generate",
          "atoms": [
            "file-write",
            "live-artifact"
          ]
        }
      ]
    },
    "capabilities": [
      "prompt:inject",
      "fs:write"
    ]
  }
}
